def permutation_coefficient(n, k):
    """Write a function to calculate the permutation coefficient of given p(n, k).

    P(n, k) = n! / (n - k)!, the number of ordered arrangements of
    ``k`` items chosen from ``n`` items without repetition.

    Returns 0 when ``k > n`` and raises ``ValueError`` for negative
    arguments.
    """
    if n < 0 or k < 0:
        raise ValueError("n and k must be non-negative")
    if k > n:
        return 0
    result = 1
    for i in range(k):
        result *= n - i
    return result
